import{_ as a,o as e,c as r,a2 as s}from"./chunks/framework.CfwCq2QB.js";const o="/dev-go-docs/shots/0.2.3/zh-CN/light/sync-backup-card.png",_=JSON.parse('{"title":"备份与同步","description":"","frontmatter":{},"headers":[],"relativePath":"settings/sync.md","filePath":"settings/sync.md"}'),n={name:"settings/sync.md"};function l(i,t,d,c,h,p){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="备份与同步" tabindex="-1">备份与同步 <a class="header-anchor" href="#备份与同步" aria-label="Permalink to &quot;备份与同步&quot;">​</a></h1><p>一句话：全部配置可导出为 JSON 再导入（换机 / 备份）；需要跨设备的数据由后台自动分片同步，登录同一浏览器账号即可。</p><h2 id="备份-导出-导入" tabindex="-1">备份（导出 / 导入） <a class="header-anchor" href="#备份-导出-导入" aria-label="Permalink to &quot;备份（导出 / 导入）&quot;">​</a></h2><p>设置页「通用 → 数据备份」：</p><ul><li><strong>导出配置</strong>：生成一份 JSON 文件，包含快捷导航、网络与代理、翻译、AI 模型、划词动作与停用列表、网页增强列表、外观与语言等全部设置</li><li><strong>导入配置</strong>：选择备份文件立即生效，无效条目会跳过并提示「已导入 N 项（跳过 M 项无效数据）」</li><li>备份文件带应用标识和版本号，导入时会校验类型，不是 DevGo 的备份文件会直接拒绝</li></ul><img src="'+o+'" alt="「数据备份」卡片：导出配置 / 导入配置"><p><em>图：「数据备份」卡片——导出 / 导入全部配置；API Key 不会写进备份文件。</em></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>API Key 不写入备份文件</strong>（避免明文泄露）。换机导入后，翻译模型和对话模型的 Key 需要在 <a href="/dev-go-docs/settings/models.html">AI 模型</a>里重新填写。</p></div><h2 id="跨设备同步" tabindex="-1">跨设备同步 <a class="header-anchor" href="#跨设备同步" aria-label="Permalink to &quot;跨设备同步&quot;">​</a></h2><p>不用手动导出导入的部分：登录同一浏览器账号（Chrome 账号的同步），以下数据自动带到其他设备：</p><ul><li><strong>快捷导航</strong>（新标签页的站点、分类、固定栏）</li><li><strong>代理配置</strong>（网络模式、代理服务器、规则列表等）</li></ul><p>同步在后台自动分片进行，单项数据过大或同步空间满（Chrome 上限 100KB）时会在「通用 → 跨设备同步」里提示；「立即同步」可手动触发。代理是否接管浏览器由各设备自己在网络面板确认，不会随同步强推。</p><h2 id="什么用备份、什么用同步" tabindex="-1">什么用备份、什么用同步？ <a class="header-anchor" href="#什么用备份、什么用同步" aria-label="Permalink to &quot;什么用备份、什么用同步？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>换新电脑 / 重装浏览器</td><td>导出 → 导入，一次搬完</td></tr><tr><td>多台设备日常保持一致</td><td>登录同一浏览器账号，同步自动完成</td></tr><tr><td>只想搬快捷导航</td><td>新标签页的导入 / 导出（只含导航）更轻量</td></tr></tbody></table>',14)])])}const g=a(n,[["render",l]]);export{_ as __pageData,g as default};
